      "content": "name: \"DSH-action\"\ndescription: \"DeepSeek coding tasks with controlled and native DSH composition, ecosystem extensions, and GitHub automation\"\nauthor: \"Lixiaoyiao\"\nbranding:\n  icon: \"code\"\n  color: \"blue\"\n\ninputs:\n  # BEGIN GENERATED ACTION INPUTS\n  worker-network:\n    description: \"Sole Worker public-egress switch, independent of mode, trust and plugin flags. Defaults to true; false requires Docker and retains the necessary model proxy.\"\n    required: false\n    default: \"true\"\n  comment-mode:\n    description: \"append creates one reply per run/attempt; update reuses the latest matching bot reply.\"\n    required: false\n    default: \"append\"\n  diagnostics:\n    description: \"Diagnostic detail: off, basic, or detailed (bounded redacted artifact).\"\n    required: false\n    default: \"basic\"\n  dsh-profile:\n    description: \"Trusted repository Profile directory; auto discovers .dsh at the trusted base/default commit.\"\n    required: false\n    default: \"auto\"\n  dsh-env:\n    description: \"JSON array of additional Worker environment variable names. Never Controller credentials.\"\n    required: false\n    default: \"[]\"\n  deepseek-api-key:\n    description: \"DeepSeek API key. Kept by the controller-side credential proxy; never passed to DSH or repository code.\"\n    required: true\n  github-token:\n    description: \"GitHub token used only by the trusted controller.\"\n    required: false\n    default: \"${{ github.token }}\"\n  allow-write:\n    description: \"Allow trusted same-repository task/fix/implement writes after all trust gates pass.\"\n    required: false\n    default: \"false\"\n  natural-language-write:\n    description: \"Allow an explicit natural-language change request to request write access. Ambiguous requests stay read-only. This independent opt-in never replaces allow-write, actor trust, validation or Gateway authorization; legacy commands are unchanged.\"\n    required: false\n    default: \"false\"\n  command:\n    description: \"Optional explicit operation: task, review, diagnose, fix, implement, or auto.\"\n    required: false\n    default: \"auto\"\n  task-access:\n    description: \"Capability requested by an explicit task: read or write. Natural-language mentions use their separate natural-language-write opt-in. Write still requires allow-write and every policy gate.\"\n    required: false\n    default: \"read\"\n  prompt:\n    description: \"Trusted task prompt. With command=auto on dispatch/schedule events, a non-empty prompt selects generic task mode.\"\n    required: false\n    default: \"\"\n  prompt-file:\n    description: \"Explicit maintainer-selected UTF-8 task file from the repository default branch, pinned to its resolved commit SHA. Mutually exclusive with prompt; interactive command instructions keep precedence. Text only.\"\n    required: false\n    default: \"\"\n  context-files:\n    description: \"JSON array of at most 8 explicit repository-relative text paths from the bound task revision. Attached as untrusted context, never authority; no globs, symlinks, runner paths, images, or Office files.\"\n    required: false\n    default: \"[]\"\n  model:\n    description: \"Optional DeepSeek Agent model identifier for controlled and native modes. Empty preserves the pinned DSH default (deepseek-flash); accepts up to 128 ASCII letters, digits, dots, underscores, or hyphens.\"\n    required: false\n    default: \"\"\n  reasoning-effort:\n    description: \"Optional DeepSeek Agent thinking effort: off, low, high, or max. Empty preserves the pinned DSH provider default (high); off disables thinking. Applies to controlled and native modes.\"\n    required: false\n    default: \"\"\n  session-mode:\n    description: \"Session opt-in: off, auto, save, or resume. Auto creates or continues the latest successful compatible checkpoint by key, with verified key-scoped concurrency and run-name history. Requires Docker; explicit save/resume remain supported.\"\n    required: false\n    default: \"off\"\n  session-key:\n    description: \"Maintainer-selected logical Session key, 1-64 ASCII letters, digits, dot, underscore or hyphen. Auto keys are case-insensitive, matching GitHub concurrency. Bound to repository, workflow job, task and runtime; never grants authority.\"\n    required: false\n    default: \"\"\n  session-source-run-id:\n    description: \"For session-mode=resume, the explicit successful producer Actions run ID. Only its verified current attempt and latest compatible checkpoint may be restored.\"\n    required: false\n    default: \"\"\n  session-retention-days:\n    description: \"Checkpoint retention, 1-7 days. Saves the complete raw DSH Session, referenced official attachment bytes and a bounded provenance manifest; credentials and Controller authorization are excluded.\"\n    required: false\n    default: \"3\"\n  trigger-phrase:\n    description: \"Maintainer-controlled literal starting a direct, unquoted, non-code comment line. Accepts natural-language tasks and legacy commands. Routing only; it never grants authority.\"\n    required: false\n    default: \"@dsh\"\n  label-trigger:\n    description: \"Optional exact label that routes Issue tasks or pull request reviews. Empty disables this route.\"\n    required: false\n    default: \"\"\n  assignee-trigger:\n    description: \"Optional exact assignee login that routes Issue tasks or pull request reviews. Empty disables this route.\"\n    required: false\n    default: \"\"\n  allowed-actors:\n    description: \"Comma-separated maintainer routing allowlist for originating actors. * preserves the default route; authorization remains separate.\"\n    required: false\n    default: \"*\"\n  allowed-bots:\n    description: \"Comma-separated bot allowlist. Empty preserves the fail-closed bot write gate; listed bots still need repository write permission.\"\n    required: false\n    default: \"\"\n  include-comments-by-actor:\n    description: \"Optional comma-separated allowlist for historical comments included as untrusted context. The audited trigger comment is retained.\"\n    required: false\n    default: \"\"\n  exclude-comments-by-actor:\n    description: \"Optional comma-separated deny list for historical comment context. Exclusion wins over inclusion.\"\n    required: false\n    default: \"\"\n  base-branch:\n    description: \"Maintainer-selected base branch for Issue and automation tasks. Empty uses the trusted repository default branch; PR fixes stay bound to their head.\"\n    required: false\n    default: \"\"\n  branch-prefix:\n    description: \"Validated prefix for Controller-created task branches.\"\n    required: false\n    default: \"dsh/\"\n  branch-name-template:\n    description: \"Optional deterministic branch template using {{prefix}}, {{key}}, {{operation}}, {{entityType}}, and {{entityNumber}}; {{prefix}} and {{key}} are required.\"\n    required: false\n    default: \"\"\n  task-output-schema:\n    description: \"Optional bounded maintainer-owned JSON Schema for a Controller-validated final taskOutput. Strict envelope validation still applies; it never replaces result-json or grants authority.\"\n    required: false\n    default: \"\"\n  dsh-mode:\n    description: \"DSH composition ownership: controlled preserves the Controller-owned ToolRuntime policy; experimental native uses the official DSH headless Profile, MCP, Bundle, Plugin, Skill, Subagent, and Workflow graph inside the Action's Docker safety boundary.\"\n    required: false\n    default: \"controlled\"\n  dsh-version:\n    description: \"Pinned @deepseek-ai/dsh version. The Action accepts only the audited 0.2.1-rc.2 runtime.\"\n    required: false\n    default: \"0.2.1-rc.2\"\n  dsh-executable:\n    description: \"Trusted capability input. Optional absolute path to a preinstalled DSH executable; host mode executes it without a container boundary.\"\n    required: false\n    default: \"\"\n  isolation:\n    description: \"Trusted capability input selecting the DSH isolation backend. 'none' removes the OS/container boundary; Docker is required for untrusted review data, writes, and extensions.\"\n    required: false\n    default: \"docker\"\n  container-image:\n    description: \"Trusted worker-code input. Every value must be one Docker/OCI image reference and cannot be parsed as a Docker option; extensions and writes require a full name@sha256 digest.\"\n    required: false\n    default: \"docker.io/library/node:24.18.0-bookworm@sha256:5711a0d445a1af54af9589066c646df387d1831a608226f4cd694fc59e745059\"\n  timeout-minutes:\n    description: \"Overall setup/execution deadline shared by runtime and extension install, DSH turns, command tools, and validation. Fixed short cleanup/finalization grace may run after it.\"\n    required: false\n    default: \"20\"\n  max-findings:\n    description: \"Maximum high-confidence findings to publish.\"\n    required: false\n    default: \"20\"\n  run-tests:\n    description: \"Must be true for every code, Git ref, and pull-request mutation. false denies the mutation and is not a validation waiver.\"\n    required: false\n    default: \"true\"\n  test-commands:\n    description: 'Non-empty JSON array of credential-free argv arrays required for every write, e.g. [[\"npm\",\"test\"]]. Every command must pass; Controller credentials in argv are rejected.'\n    required: false\n    default: \"[]\"\n  validation-integrity:\n    description: \"Controller-owned validation-definition policy: off records, warn reports, strict blocks high-confidence weakening and replays baseline controls when needed.\"\n    required: false\n    default: \"warn\"\n  base-url:\n    description: \"Trusted upstream for model requests and compatible DeepSeek API routes. Does not select Worker egress or the target URL of native HTTP fetch.\"\n    required: false\n    default: \"https://api.deepseek.com\"\n  web-search-base-url:\n    description: \"Trusted upstream for official DSH Messages-based web search through the restricted Controller proxy. Worker public egress is controlled by worker-network.\"\n    required: false\n    default: \"https://api.deepseek.com/anthropic/v1\"\n  bot-user-id:\n    description: \"Numeric ID of the bot account that owns tracking comments. Defaults to github-actions[bot].\"\n    required: false\n    default: \"41898282\"\n  progress-comment:\n    description: \"Create or update one controller-owned sticky comment at major lifecycle stages, reusing the operation's result marker.\"\n    required: false\n    default: \"true\"\n  max-turns:\n    description: \"Maximum fresh DSH turns across tool requests and validation repair attempts.\"\n    required: false\n    default: \"3\"\n  permission-profile:\n    description: \"Agent tool preset: strict preserves v0.4 behavior, standard grants trusted coding conveniences, and custom uses the exact allow/deny lists.\"\n    required: false\n    default: \"strict\"\n  allowed-tools:\n    description: \"JSON allowlist of Action/controlled capabilities. controlled accepts workspace.*, native.*, command.*, typed github.*, mcp.*, and plugin.* IDs; native rejects mcp./plugin. grants because DSH owns that inventory.\"\n    required: false\n    default: \"[]\"\n  disallowed-tools:\n    description: \"JSON deny list using the same exact tool IDs as allowed-tools. Deny always wins after preset expansion.\"\n    required: false\n    default: \"[]\"\n  tool-config:\n    description: \"Versioned JSON manifest of maintainer-owned fixed-argv command tools. Model-provided argv and controller credentials in argv are rejected; common direct shell executables are also denied.\"\n    required: false\n    default: '{\"schemaVersion\":1,\"commands\":[]}'\n  mcp-config:\n    description: \"Versioned maintainer-owned official DSH MCP config. controlled declares exact tools/budgets; native declares the server, owner-level workspaceWrite/network, toolCallTimeoutMs, and explicit credentialEnv/credentialHeaders because DSH discovers tools.\"\n    required: false\n    default: '{\"schemaVersion\":1,\"servers\":[]}'\n  plugin-config:\n    description: \"Versioned maintainer-owned DSH Bundle/Plugin config. Native entries are definition-only, with direct-Plugin credentialConfig, and load through official Profile/Cordis composition. Startup executes trusted worker code; every package requires an exact semver or GitHub commit pin.\"\n    required: false\n    default: '{\"schemaVersion\":1,\"bundles\":[],\"plugins\":[]}'\n  allow-plugin-install:\n    description: \"Allow startup of explicitly configured and pinned third-party DSH Bundles/Plugins. Disabled by default because installation and startup execute trusted code.\"\n    required: false\n    default: \"false\"\n  # END GENERATED ACTION INPUTS\noutputs:\n  dsh-mode:\n    description: \"Resolved DSH mode: controlled, native, or none\"\n  dsh-composition:\n    description: \"Stable selected DSH composition identity, or none\"\n  conclusion:\n    description: \"success, neutral, or failure\"\n  operation:\n    description: \"Resolved operation: task, review, diagnose, fix, implement, or none\"\n  summary:\n    description: \"Validated final summary for any operation, or a safe failure summary\"\n  review-summary:\n    description: \"Backward-compatible alias of summary\"\n  findings-count:\n    description: \"Selected review findings, or validated agent findings for other operations\"\n  branch-name:\n    description: \"Created or updated Controller task branch\"\n  pull-request-url:\n    description: \"Created pull request URL\"\n  commit-sha:\n    description: \"Commit created by a successful fix operation\"\n  trust:\n    description: \"Resolved execution profile: untrusted, trusted-read, trusted-write, or none\"\n  permission-profile:\n    description: \"Resolved Agent permission profile: strict, standard, custom, or none\"\n  effective-tools:\n    description: \"Backward-compatible Controller-plane canonical capability array. It is exact for controlled mode but never describes native DSH inventory; use result-json.toolPolicy.observedTools for native telemetry.\"\n  network-access:\n    description: \"Effective worker network: host-gateway, mediated-web, bridge, or none before permission resolution\"\n  workspace-write:\n    description: \"Whether the effective Agent tools can modify the disposable workspace\"\n  trusted-extensions:\n    description: \"JSON array of Action-admitted MCP, Bundle, and Plugin owners; native network/write values describe shared worker authority, not per-tool grants\"\n  duration-ms:\n    description: \"Total controller duration in milliseconds\"\n  comment-id:\n    description: \"Sticky progress/result comment ID when progress tracking was available\"\n  error-code:\n    description: \"Stable failure code, empty on success or neutral completion\"\n  error-message:\n    description: \"Redacted and bounded failure message\"\n  extension-profile-digest:\n    description: \"SHA-256 digest of the redacted controlled extension profile or native admission audit, empty when unavailable\"\n  tool-receipts:\n    description: \"JSON object with bounded controller/DSH receipt arrays and truncation metadata; never an authorization input\"\n  task-output:\n    description: \"JSON-encoded maintainer-defined task output after Controller schema validation; empty when not configured or unavailable\"\n  result-json:\n    description: \"Versioned JSON envelope containing status, result, policy, permissions, tool-policy ownership audit, known-authority audit, extension audit, tool receipts, timing, publication, validation integrity, write, and error details\"\n\nruns:\n  using: \"node24\"\n  main: \"dist/index.js\"\n"
    },
